export default "if (!HTMLCollection.prototype.forEach) HTMLCollection.prototype.forEach = Array.prototype.forEach;\n\n(() => {\n      const panels = { profile: 'accountProfilePanel', permissions: 'permissionManagementPanel', users: 'accountUsersPanel', audit: 'accountAuditPanel' };\n      let activeTab = 'profile';\n      const setAccountTab = tab => {\n        activeTab = Object.prototype.hasOwnProperty.call(panels, tab) ? tab : 'profile';\n        document.querySelectorAll('[data-account-tab]').forEach(button => {\n          const active = button.dataset.accountTab === activeTab;\n          button.classList.toggle('button-accent', active);\n          button.classList.toggle('button-quiet', !active);\n          button.setAttribute('aria-selected', String(active));\n        });\n        Object.entries(panels).forEach(([key, id]) => { const panel = document.getElementById(id); if (panel) panel.hidden = key !== activeTab; });\n      };\n      document.querySelectorAll('[data-account-tab]').forEach(button => button.addEventListener('click', () => setAccountTab(button.dataset.accountTab)));\n      document.querySelector('[data-view=\"account\"]')?.addEventListener('click', () => setAccountTab('profile'));\n      const permissionPanel = document.getElementById('permissionManagementPanel');\n      if (permissionPanel) new MutationObserver(() => { if (activeTab !== 'permissions' && !permissionPanel.hidden) permissionPanel.hidden = true; }).observe(permissionPanel, { attributes: true, attributeFilter: ['hidden'] });\n      setAccountTab('profile');\n    })();\n\n(() => {\r\n      const addFilterToolbar = (body, html, apply, reset) => {\r\n        const table = body?.closest('.excel-wrap');\r\n        if (!table || table.previousElementSibling?.dataset.tprmFilters) return;\r\n        const toolbar = document.createElement('div');\r\n        toolbar.className = 'toolbar';\r\n        toolbar.dataset.tprmFilters = 'true';\r\n        toolbar.innerHTML = html;\r\n        table.before(toolbar);\r\n        toolbar.querySelectorAll('input, select').forEach(control => control.addEventListener('input', apply));\r\n        toolbar.querySelectorAll('select').forEach(control => control.addEventListener('change', apply));\r\n        toolbar.querySelector('button').addEventListener('click', reset);\r\n        return toolbar;\r\n      };\r\n      const questionnaireToolbar = addFilterToolbar(document.querySelector('#questionnaireBody'), '<label class=\"search-box\"><span>/</span><input type=\"search\" placeholder=\"Search vendor assessments...\" autocomplete=\"off\"></label><select><option value=\"all\">All statuses</option><option>Draft</option><option>In progress</option><option>Complete</option><option>Expired</option><option>Final</option></select><select><option value=\"all\">All results</option><option>Pending</option><option>Approved</option><option>Approved with Conditions</option><option>Rejected</option></select><button class=\"button button-quiet\" type=\"button\">Clear filters</button>', () => { questionnaireFilter.query = questionnaireToolbar.querySelector('input').value; questionnaireFilter.status = questionnaireToolbar.querySelectorAll('select')[0].value; questionnaireFilter.result = questionnaireToolbar.querySelectorAll('select')[1].value; renderQuestionnaires(); }, () => { questionnaireFilter = { query: '', status: 'all', result: 'all' }; questionnaireToolbar.querySelector('input').value = ''; questionnaireToolbar.querySelectorAll('select').forEach(select => { select.value = 'all'; }); renderQuestionnaires(); });\r\n      const tprmToolbar = addFilterToolbar(document.querySelector('#tprmBody'), '<label class=\"search-box\"><span>/</span><input type=\"search\" placeholder=\"Search third-party risks...\" autocomplete=\"off\"></label><select><option value=\"all\">All assessment statuses</option><option>Not started</option><option>Complete</option><option>Accepted</option></select><select><option value=\"all\">All relationship statuses</option><option>Active</option><option>Offboarded</option><option>Expired</option><option>Terminated</option></select><select><option value=\"all\">All CIA risk levels</option><option>High Risk (Tier 1)</option><option>Medium Risk (Tier 2)</option><option>Low Risk (Tier 3)</option></select><button class=\"button button-quiet\" type=\"button\">Clear filters</button>', () => { tprmFilter.query = tprmToolbar.querySelector('input').value; tprmFilter.status = tprmToolbar.querySelectorAll('select')[0].value; tprmFilter.relationshipStatus = tprmToolbar.querySelectorAll('select')[1].value; tprmFilter.riskLevel = tprmToolbar.querySelectorAll('select')[2].value; renderTprmRows(); }, () => { tprmFilter = { query: '', status: 'all', relationshipStatus: 'all', riskLevel: 'all' }; tprmToolbar.querySelector('input').value = ''; tprmToolbar.querySelectorAll('select').forEach(select => { select.value = 'all'; }); renderTprmRows(); });\r\n    })();\n"